// Wpisz tutaj ID swoich 8 stacji z Airly
msg.payload = [
    119289, 
    86755, 
    116567, 
    87152, 
    37, 
    86758, 
    3426, 
    86788
];
return msg;

if (!msg.payload || !msg.payload.current) return null;

let current = msg.payload.current.values;
let forecast = msg.payload.forecast || [];
let stationId = msg.station_id || "unknown";
let timestamp = msg.payload.current.tillDateTime;

// Wyciąganie bieżących wartości
let data = {};
current.forEach(v => {
    data[v.name] = v.value;
});

let pm10_current = data["PM10"] || 0;
let is_smog_alert = pm10_current > 50; // Prosty próg dla alertów

// --- WYJŚCIE 1: Dla PostgreSQL (Bez zmian) ---
let msgSQL = {
    query: "INSERT INTO airly_readings (station_id, measurement_time, pm1, pm25, pm10, temperature, humidity) VALUES ($1, $2, $3, $4, $5, $6, $7);",
    params: [
        stationId, timestamp, data["PM1"] || null, data["PM25"] || null, data["PM10"] || null, data["TEMPERATURE"] || null, data["HUMIDITY"] || null
    ]
};

// --- WYJŚCIE 2: Dla RabbitMQ (Podział na strumienie) ---
let rabbitMessages = [];

// Strumień 1: Surowe dane (np. do przyszłych modeli ML)
rabbitMessages.push({
    payload: { station: stationId, time: timestamp, raw_readings: data },
    routingKey: `telemetry.raw.station_${stationId}`
});

// Strumień 2: Historia dla systemu RAG
rabbitMessages.push({
    payload: { station: stationId, time: timestamp, current_values: data, record_type: "historical" },
    routingKey: `telemetry.rag.historical.station_${stationId}`
});

// Strumień 3: Prognoza dla systemu RAG (tylko jeśli istnieje)
if (forecast.length > 0) {
    rabbitMessages.push({
        payload: { station: stationId, time: timestamp, forecast: forecast, record_type: "forecast" },
        routingKey: `telemetry.rag.forecast.station_${stationId}`
    });
}

// Strumień 4: Szybkie alerty smogowe
if (is_smog_alert) {
    rabbitMessages.push({
        payload: { station: stationId, time: timestamp, pm10: pm10_current, alert: "Przekroczenie PM10!" },
        routingKey: `telemetry.alert.station_${stationId}`
    });
}

return [msgSQL, rabbitMessages];

// 1. ZABEZPIECZENIE FORMATU WEJŚCIOWEGO
let data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
let station = data.station || "nieznana";
let record_type = data.record_type || "historical"; // Z naszego parsera

// 2. TWARDE METADANE CZASOWE
let dateObj = new Date(data.time);
let unix_timestamp = Math.floor(dateObj.getTime() / 1000); // Epoch 
let date_string = dateObj.toISOString().split('T')[0];     // YYYY-MM-DD
let hour = dateObj.getHours();

let time_of_day = "";
if (hour >= 6 && hour < 9) time_of_day = "rano";
else if (hour >= 9 && hour < 13) time_of_day = "przedpołudnie";
else if (hour >= 13 && hour < 17) time_of_day = "popołudnie";
else if (hour >= 17 && hour < 22) time_of_day = "wieczór";
else time_of_day = "noc";

// 3. DETERMINISTYCZNE ID (Ochrona przed duplikatami)
// Kombinacja stacja + data + godzina + typ_rekordu
let uniqueString = `${station}-${date_string}-${hour}-${record_type}`;
let hash = 0;
for (let i = 0; i < uniqueString.length; i++) {
    hash = ((hash << 5) - hash) + uniqueString.charCodeAt(i);
    hash |= 0; 
}
let hex = Math.abs(hash).toString(16).padStart(8, '0');
let deterministic_uuid = `${hex}-0000-4000-8000-000000000000`; // Format zgodny z UUID w Qdrant

// 4. GENEROWANIE NARRACJI I TAGÓW ZALEŻNIE OD TYPU DANYCH
let textPrompt = "";
let suitability_tags = [];
let pm10_reference = 0;
let dayOfWeek = dateObj.toLocaleDateString('pl-PL', { weekday: 'long' });

if (record_type === "historical") {
    // --- OBRÓBKA DANYCH HISTORYCZNYCH/BIEŻĄCYCH ---
    let current = data.current_values || {};
    pm10_reference = current.PM10 || 0;
    let pm25_current = current.PM25 || 0;
    let status = "";
    let health_impact = "";

    if (pm10_reference <= 20) {
        status = "BARDZO DOBRY";
        suitability_tags = ["sport_excellent", "ventilation_excellent"];
        health_impact = "Powietrze jest rześkie. Idealne warunki do głębokiego oddychania na zewnątrz.";
    } else if (pm10_reference <= 50) {
        status = "UMIARKOWANY";
        suitability_tags = ["sport_ok", "ventilation_ok"];
        health_impact = "Powietrze akceptowalne. Osoby bardzo wrażliwe mogą odczuwać delikatny dyskomfort.";
    } else {
        status = "ZŁY (SMOG)";
        suitability_tags = ["sport_unsuitable", "ventilation_unsuitable", "health_hazard"];
        health_impact = "Wysokie stężenie pyłów. Oddychanie na zewnątrz może powodować duszności i kaszel.";
    }

    textPrompt = `Zapis pomiarów: W ${dayOfWeek} ${time_of_day} (${date_string} godz. ${hour}:00), na stacji ${station}, ` +
                 `odnotowano ${status} stan powietrza. PM10: ${pm10_reference} µg/m³. ` +
                 `Wpływ na zdrowie: ${health_impact}`;

} else if (record_type === "forecast") {
    // --- OBRÓBKA PROGNOZY ---
    let forecastArr = data.forecast || [];
    let best_forecast_time = "brak danych";
    pm10_reference = 9999; 
    let trend_narrative = "";

    forecastArr.forEach(f => {
        let f_pm10_obj = f.values.find(v => v.name === "PM10");
        if (f_pm10_obj && f_pm10_obj.value < pm10_reference) {
            pm10_reference = f_pm10_obj.value;
            let fDate = new Date(f.tillDateTime);
            best_forecast_time = `${fDate.getHours()}:00 (${fDate.toISOString().split('T')[0]})`;
        }
    });

    if (pm10_reference <= 20) {
        suitability_tags = ["forecast_sport_excellent", "forecast_ventilation_excellent"];
        trend_narrative = `Najlepsze okno na aktywność fizyczną lub wietrzenie przewidywane jest na godzinę ${best_forecast_time}, gdy stężenie pyłów spadnie do idealnego poziomu ok. ${Math.round(pm10_reference)} µg/m³.`;
    } else {
        suitability_tags = ["forecast_sport_poor"];
        trend_narrative = `Nie przewiduje się drastycznej poprawy. Najmniejsze zanieczyszczenie (ok. ${Math.round(pm10_reference)} µg/m³) wystąpi w okolicach ${best_forecast_time}. Warto wstrzymać się z długimi treningami.`;
    }

    textPrompt = `Analiza prognozy wygenerowana w ${dayOfWeek} ${time_of_day} dla okolicy stacji ${station}. Wnioski z prognozy: ${trend_narrative}`;
}

// 5. PAKOWANIE DO QDRANTA I OLLAMY
msg.airly_metadata = {
       "point_id": deterministic_uuid, 
       "station_id": station.toString(),
       "timestamp": unix_timestamp,
       "date_string": date_string,
       "time_of_day": time_of_day,
       "record_type": record_type,
       "suitability_tags": suitability_tags,
       "narrative": textPrompt,
       "pm10_reference": pm10_reference
};

msg.payload = {
    "model": "nomic-embed-text",
    "prompt": textPrompt
};

return msg;

// 1. Pobieramy wygenerowany wektor z odpowiedzi Ollamy (nomic-embed-text)
let vector = msg.payload.embedding;

// 2. Pobieramy metadane przygotowane w węźle "Przygotuj Tekst dla AI"
let metadata = msg.airly_metadata;

// 3. Budujemy ostateczny payload dla bazy Qdrant
// API Qdranta /collections/{name}/points domyślnie wykonuje UPSERT (Insert or Update)
msg.payload = {
    "points": [
        {
            "id": metadata.point_id, // Używamy wygenerowanego, deterministycznego UUID!
            "vector": vector,
            "payload": metadata      // Zapisujemy całą strukturę tagów i narracji
        }
    ]
};

return msg;

// Bierzemy pytanie i zlecamy Ollamie zamianę go na wektor
msg.payload = {
    "model": "nomic-embed-text",
    "prompt": msg.question
};
return msg;

let vector = msg.payload.embedding;
let question = (msg.question || "").toLowerCase();

// Inicjalizujemy pustą listę filtrów "must" (warunki konieczne dla bazy Qdrant)
let must_filters = [];

// --- EKSTRAKCJA INTENCJI I FILTROWANIE HYBRYDOWE ---
// W środowisku produkcyjnym takie filtry mógłby generować mniejszy model językowy (tzw. Query Router).
// Na potrzeby testów implementujemy proste reguły oparte na słowach kluczowych.

// 1. Typ rekordu (Historia vs Prognoza)
if (question.includes("jutro") || question.includes("kiedy") || question.includes("będzie")) {
    must_filters.push({
        "key": "record_type",
        "match": { "value": "forecast" }
    });
} else if (question.includes("wczoraj") || question.includes("było")) {
    must_filters.push({
        "key": "record_type",
        "match": { "value": "historical" }
    });
}

// 2. Filtr czasowy "wczoraj" (Hard filter - Qdrant odrzuci wektory z innych dni)
if (question.includes("wczoraj")) {
    let yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    let dateString = yesterday.toISOString().split('T')[0]; 

    must_filters.push({ 
        "key": "date_string", 
        "match": { "value": dateString } 
    });
}

// 3. Filtr pory dnia
if (question.includes("wieczór") || question.includes("wieczorem")) {
    must_filters.push({ 
        "key": "time_of_day", 
        "match": { "value": "wieczór" } 
    });
}

// --- BUDOWA ZAPYTANIA HYBRYDOWEGO ---
let qdrant_payload = {
    "vector": vector,
    "limit": 3, // Pobieramy 3 najlepsze konteksty (a nie 1), by LLM miał szerszy obraz
    "with_payload": true
};

// Jeśli wykryliśmy jakiekolwiek filtry, dodajemy je do zapytania Qdranta
if (must_filters.length > 0) {
    qdrant_payload.filter = {
        "must": must_filters
    };
}

msg.payload = qdrant_payload;
return msg;

let qdrantData = msg.qdrant_context;
let sqlData = msg.payload; // Wynik z węzła PostgreSQL

// 1. Formatowanie danych wektorowych (Semantyka i Prognozy)
let contextText = "Brak danych semantycznych z bazy Qdrant.";
if (qdrantData && qdrantData.length > 0) {
    contextText = qdrantData.map(r => r.payload.narrative).join("\n---\n");
}

// 2. Formatowanie danych relacyjnych (Twarde fakty z PostgreSQL)
let sqlText = "Brak dokładnych danych SQL.";
if (sqlData && Array.isArray(sqlData)) {
    // Formatujemy tablicę JSON do ładnego tekstu
    sqlText = sqlData.map(row => JSON.stringify(row)).join("\n");
}

// 3. MAGIA HYBRYDOWEGO RAG: Łączenie źródeł
let systemPrompt = `Jesteś ekspertem ds. jakości powietrza. Odpowiadasz na pytanie użytkownika na podstawie dwóch źródeł danych.

[ŹRÓDŁO 1: BAZA WIEDZY I PROGNOZY (Kontekst semantyczny Qdrant)]
${contextText}

[ŹRÓDŁO 2: TWARDE DANE Z CZUJNIKÓW (Odczyty i agregacje z PostgreSQL)]
${sqlText}

INSTRUKCJE DLA CIEBIE:
1. Używaj języka polskiego, bądź pomocny i naturalny.
2. Jeśli pytanie dotyczy konkretnych wartości historycznych (np. "jaka była temperatura", "najwyższe zapylenie"), zawsze traktuj dane z [ŹRÓDŁO 2] jako ostateczną prawdę absolutną.
3. Jeśli pytanie dotyczy prognoz lub zaleceń (np. "czy iść biegać jutro"), bazuj na narracjach z [ŹRÓDŁO 1].
4. Jesteś precyzyjnym asystentem jakości powietrza.
5. Odpowiadaj bezpośrednio i jednoznacznie w 1-2 zdaniach. Od razu podawaj wynik.
6. Nigdy nie używaj zwrotów powitalnych ani pożegnalnych (np. 'Witaj', 'Zwracam się do Ciebie', 'Czas na decyzję').
7. Nigdy nie podawaj technicznych numerów stacji (np. 86755) ani nie odwołuj się do słowa [ŹRÓDŁO]. Zamiast tego mów 'w Twojej okolicy'.
`;

msg.payload = {
    "model": "llama3",
    "prompt": systemPrompt + "\n\nPYTANIE UŻYTKOWNIKA: " + msg.question,
    "stream": false
};

return msg;

// 1. Zapisujemy wyniki z Qdranta w innej zmiennej, 
// ponieważ węzeł Postgres nadpisze nam 'msg.payload'
msg.qdrant_context = msg.payload.result;

let question = (msg.question || "").toLowerCase();
let sqlQuery = "";

// 2. Prosty Text-to-SQL (Tłumaczenie intencji na SQL)
// (W środowisku produkcyjnym ten krok wykonuje mniejszy model LLM agenta bazodanowego)
if (question.includes("wczoraj") || question.includes("było")) {
    // Agregacja twardych danych z wczoraj
    sqlQuery = "SELECT MAX(pm10) as max_pm10, MIN(pm10) as min_pm10, ROUND(AVG(temperature)::numeric, 1) as avg_temp FROM airly_readings WHERE measurement_time >= current_date - interval '1 day' AND measurement_time < current_date;";
} else {
    // Domyślnie: najnowsze czyste fakty dla kontekstu bieżącego
    sqlQuery = "SELECT pm10, pm25, temperature, humidity, measurement_time FROM airly_readings ORDER BY measurement_time DESC LIMIT 3;";
}

// 3. Węzeł PostgreSQL wymaga zapytania w 'msg.payload.query' lub 'msg.payload'
msg.payload = {
    query: sqlQuery
};

return msg;

if (!msg.startTime) {
    node.error("Brak msg.startTime!");
    return null;
}

let start = Number(msg.startTime); 
let latencyMs = Date.now() - start;
let seconds = Number((latencyMs / 1000).toFixed(4));

// Tworzymy czystą, nową wiadomość dla węzła Prometheus
let newMsg = {};

// Pakujemy wartość, operację i etykiety bezpośrednio w payload
newMsg.payload = {
    val: seconds,
    op: "set",
    labels: { source: "node-red_rag" }
};

return newMsg;

